			INSERT [dbo].[ControlTarget] ([Depot], [CF_Run_Number], [CF_or_COT], [Bay], [Number_of_cycles_per_day], [CF_Scanner_Run], [Target]) VALUES (N'SYD', N'TYF', NULL, N'', NULL, N'TYF', N'119.9');
